const cid = ($('Webhook1').first().json.body.whatsappInboundMessage.from || '').replace(/[^0-9]/g,'');
const tel = ($('Webhook1').first().json.body.whatsappInboundMessage.from||'').replace(/[^0-9]/g,'');
const raw = $('Leer estado (finalizar)').first().json.estado_raw;
let estado = raw ? JSON.parse(raw) : { cliente:{}, productos:[], fotos:[], updated_at:0 };
let c = estado.cliente || {};

let direcciones_conocidas = [];
let cliente_conocido = false;
if (tel) {
  try {
    const ODOO = { db:'selfa2', uid:2, pwd:'17bfcdc987742e11fe6a5eaacd36d25da2174e11' };
    const call = async (model,method,a,kw) => {
      const r = await this.helpers.httpRequest({ method:'POST', url:'https://selfa2.odoo.com/jsonrpc', headers:{'Content-Type':'application/json'},
        body:{ jsonrpc:'2.0', method:'call', id:1, params:{ service:'object', method:'execute_kw', args:[ODOO.db,ODOO.uid,ODOO.pwd,model,method,a,kw||{}] } }, json:true });
      if (r.error) throw new Error(JSON.stringify(r.error)); return r.result;
    };
    const tail = tel.slice(-9);
    const leads = await call('crm.lead','search_read',[['|',['phone','like',tail],['phone_sanitized','like',tail]]],
      { fields:['contact_name','name','street','zip','city','x_tipo_cliente'], limit:20, order:'id desc' });
    if (leads && leads.length) {
      cliente_conocido = true;
      // reusar nombre y tipo del mas reciente
      const L = leads[0];
      const _nom = (L.contact_name || (L.name||'').split(' \u2014 ')[0] || '').trim();
      if (!c.nombre && _nom) c.nombre = _nom;
      if (!c.tipo_cliente && L.x_tipo_cliente) c.tipo_cliente = L.x_tipo_cliente;
      // recopilar direcciones unicas
      const seen = {};
      for (const l of leads) {
        const st = (l.street||'').trim();
        if (st && !seen[st.toLowerCase()]) {
          seen[st.toLowerCase()] = true;
          direcciones_conocidas.push({ street: st, cp: l.zip||'', city: l.city||'' });
        }
      }
      estado.cliente = c;
    }
  } catch(e) {}
}

// Si el cliente ya escribio una direccion NUEVA en esta conversacion, respetarla (no re-preguntar)
const faltan = [];
if (!c.nombre)       faltan.push('nombre y apellido');
if (!c.direccion)    faltan.push('direccion');
if (!c.cp)           faltan.push('cp');
if (!c.tipo_cliente) faltan.push('tipo de cliente');
// datos_completos SOLO si tiene direccion confirmada en el estado
const datos_completos = faltan.length===0;
return [{ json: { cliente_id: cid, telefono: tel, estado: JSON.stringify(estado), faltan, datos_completos, cliente_conocido, direcciones_conocidas } }];

const d = $('Evaluar datos').first().json;
const estado = JSON.parse(d.estado);
const c = estado.cliente || {};
const productos = estado.productos || [];
const fotos = (estado.fotos||[]).map(f => ({ wamid: f.wamid, mimetype: f.mimetype, caption: f.caption || '' }));
const algunPendiente = productos.some(p => String(p.notas||'').toUpperCase().includes('PENDIENTE'));
const completo = productos.length>0 && !algunPendiente && fotos.length>0;
// destino CRM: completo -> Solicitud de Presupuesto (29) ; incompleto -> Revisión Fran (37)
const etapa_destino = completo ? 'solicitud_presupuesto' : 'revision_fran';

// --- descripción en HTML (el campo notes de Odoo es HTML) ---
const nombresProd = productos.map(p => p.producto);
const cantidades  = productos.map(p => `${p.producto} x${p.cantidad}`);

const esc = s => String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const cap = s => { s=String(s||'').trim(); return s ? s.charAt(0).toUpperCase()+s.slice(1) : s; };
const tarjetas = productos.map(p => {
  let items='';
  const notas=(p.notas && p.notas!=='sin notas')?p.notas:'';
  const partes=notas.split(';').map(s=>s.trim()).filter(Boolean);
  for(const par of partes){
    const idx=par.indexOf(':');
    if(idx===-1){ items+='<li style="color:#cfd3d8;">'+esc(par)+'</li>'; }
    else{ const k=cap(par.slice(0,idx).replace(/_/g,' ').trim()); const v=esc(par.slice(idx+1).trim()); items+='<li style="color:#cfd3d8;margin:2px 0;"><b style="color:#ffffff;">'+k+':</b> '+v+'</li>'; }
  }
  if(fotos.length) items+='<li style="color:#cfd3d8;"><b style="color:#ffffff;">Fotos:</b> '+fotos.length+' \ud83d\udcf8</li>';
  return '<div style="margin:8px 0;padding:10px 14px;border-left:4px solid #5ea0ff;background:rgba(255,255,255,0.03);border-radius:4px;color:#e0e0e0;"><span style="font-size:14px;color:#5ea0ff;"><b>'+esc(p.cantidad)+'x '+esc(cap(p.producto))+'</b></span><ul style="margin:4px 0 0 0;padding-left:18px;color:#cfd3d8;">'+items+'</ul></div>';
}).join('');
const wa = 'https://wa.me/' + (d.telefono || c.telefono || '');

const descripcion =
  '<h3 style="margin:0 0 8px 0;color:#5ea0ff;">\ud83d\udce6 Pedido recibido por el bot de WhatsApp</h3>'
  + '<div style="margin:8px 0;padding:10px 14px;border-left:4px solid #9aa5b1;background:rgba(255,255,255,0.03);border-radius:4px;color:#e0e0e0;">'
  + '<span style="font-size:14px;color:#c8cfd8;"><b>\ud83d\udc64 Datos del cliente</b></span>'
  + '<ul style="margin:4px 0 0 0;padding-left:18px;color:#cfd3d8;list-style:none;">'
  + '<li style="color:#cfd3d8;margin:2px 0;"><b style="color:#ffffff;">Cliente:</b> '+esc(c.nombre||'-')+'</li>'
  + '<li style="color:#cfd3d8;margin:2px 0;"><b style="color:#ffffff;">Tel\u00e9fono:</b> '+esc(d.telefono||'')+'</li>'
  + '<li style="color:#cfd3d8;margin:2px 0;"><b style="color:#ffffff;">WhatsApp:</b> <a href="'+wa+'" style="color:#5ea0ff;">'+wa+'</a></li>'
  + (c.direccion ? '<li style="color:#cfd3d8;margin:2px 0;"><b style="color:#ffffff;">Direcci\u00f3n:</b> '+esc(c.direccion)+'</li>' : '')
  + (c.cp ? '<li style="color:#cfd3d8;margin:2px 0;"><b style="color:#ffffff;">C\u00f3digo postal:</b> '+esc(c.cp)+'</li>' : '')
  + (c.ciudad ? '<li style="color:#cfd3d8;margin:2px 0;"><b style="color:#ffffff;">Poblaci\u00f3n:</b> '+esc(c.ciudad)+'</li>' : '')
  + (c.tipo_cliente ? '<li style="color:#cfd3d8;margin:2px 0;"><b style="color:#ffffff;">Tipo cliente:</b> '+esc(c.tipo_cliente)+'</li>' : '')
  + '</ul></div>'
  + '<h4 style="margin:12px 0 4px 0;color:#5ea0ff;">\ud83e\uddfe Productos ('+productos.length+')</h4>'
  + tarjetas;

const _pfx = String(d.telefono||'').replace(/[^0-9]/g,'').endsWith('573166083511') ? '[PRUEBA] ' : '';
const _dir = [c.direccion, [c.cp,c.ciudad].filter(Boolean).join(' ')].filter(Boolean).join(', ');
const nombre_lead = _pfx + (c.nombre||'Cliente') + (_dir ? ' \u2014 ' + _dir : '');
const lead = {
  nombre_lead,
  phone: d.telefono,
  cliente_id: d.cliente_id,
  nombre: c.nombre||'',
  ciudad: c.ciudad||'',
  cp: c.cp||'',
  direccion: c.direccion||'',
  tipo_cliente: c.tipo_cliente||'',
  productos,
  fotos,
  etapa_destino,
  descripcion
};

let _lead_id = estado.lead_id || null;
if (!_lead_id && d.telefono) {
  try {
    const _URL='https://selfa2.odoo.com', _DB='selfa2', _UID=2, _KEY='17bfcdc987742e11fe6a5eaacd36d25da2174e11';
    const _last9 = String(d.telefono).replace(/[^0-9]/g,'').slice(-9);
    const _res = await this.helpers.httpRequest({
      method:'POST', url:_URL+'/jsonrpc', json:true,
      body:{jsonrpc:'2.0', method:'call', params:{service:'object', method:'execute_kw',
        args:[_DB,_UID,_KEY,'crm.lead','search_read',
          [['|',['phone','ilike',_last9],['phone_sanitized','ilike',_last9],['active','=',true]]],
          {fields:['id'], order:'id desc', limit:1}]}}
    });
    const _rows = _res && _res.result ? _res.result : [];
    if (_rows.length) _lead_id = _rows[0].id;
  } catch(e) {}
}
return [{
  json: {
    lead,
    etapa_destino,
    telefono: d.telefono,
    cliente_id: d.cliente_id,
    lead_id: _lead_id
  }
}];

const d = $('Evaluar datos').first().json;
let estado = JSON.parse(d.estado);
estado.fase_datos = true;
estado.updated_at = Date.now();
let lead_id = estado.lead_id || null;
// FALLBACK: si no hay lead_id en el estado, buscar lead activo por teléfono en Odoo
if (!lead_id && d.telefono) {
  try {
    const URL='https://selfa2.odoo.com', DB='selfa2', UID=2, KEY='17bfcdc987742e11fe6a5eaacd36d25da2174e11';
    const tel = String(d.telefono).replace(/[^0-9]/g,'');
    const last9 = tel.slice(-9);
    const res = await this.helpers.httpRequest({
      method:'POST', url:URL+'/jsonrpc', json:true,
      body:{jsonrpc:'2.0', method:'call', params:{service:'object', method:'execute_kw',
        args:[DB,UID,KEY,'crm.lead','search_read',
          [['|',['phone','ilike',last9],['phone_sanitized','ilike',last9],['active','=',true]]],
          {fields:['id'], order:'id desc', limit:1}]}}
    });
    const rows = res && res.result ? res.result : [];
    if (rows.length) { lead_id = rows[0].id; estado.lead_id = lead_id; }
  } catch(e) { /* si falla la búsqueda, seguimos con null y el update se salta abajo */ }
}
return [{ json: {
