const tel = String(L.phone).replace(/[^0-9]/g,'');
const pfx = tel.endsWith('573166083511') ? '[PRUEBA] ' : '';
const nombreLead = pfx + (L.nombre || L.phone) + ' \u2014 ' + L.productos.map(p => p.cantidad + 'x ' + p.producto).join(', ');
const existenteId = $json.lead_existente_id ? parseInt($json.lead_existente_id) : null;
async function _odoo(model, method, args, kwargs){
  const r = await this.helpers.httpRequest({ method:'POST', url:'https://selfa2.odoo.com/jsonrpc',
    headers:{'Content-Type':'application/json'},
    body:{ jsonrpc:'2.0', method:'call', id:1, params:{ service:'object', method:'execute_kw',
      args:['selfa2', 2, '17bfcdc987742e11fe6a5eaacd36d25da2174e11', model, method, args, kwargs||{}] } }, json:true });
  if (r.error) throw new Error(JSON.stringify(r.error));
  return r.result;
}
const vals = {
  name: nombreLead,
  contact_name: L.nombre || '',
  phone: '+' + tel,
  street: L.direccion || '',
  zip: L.cp || '',
  city: L.ciudad || '',
  description: L.descripcion,
  x_movil_cliente: tel,
  active: true
};
// ETAPAS DE CAPTACION: solo se REUSA el lead si sigue en captacion. Si ya avanzo, se crea uno NUEVO (proyecto distinto).
const ONBOARDING = [1, 28]; // New, Recopilando Informacion
let leadId = existenteId;
// verificar que el existente siga valido, activo y AUN en captacion
if (leadId) {
  const ok = await _odoo.call(this, 'crm.lead', 'search_read', [[['id','=',leadId]]], { fields:['stage_id'], context:{active_test:false} });
  if (!ok || !ok.length) { leadId = null; }
